+		tagRevision, err := GetWebhookRevision(wh)
+		if err != nil {
+			return nil, fmt.Errorf("error parsing revision from webhook %q: %v", wh.Name, err)
+		}
+		key := uniqTag{
+			tag:      tagName,
+			revision: tagRevision,
+		}
+		uniqTags[key] = true
